1	/**
2	 * routes/adapters.ts
3	 *
4	 * CF-native handler for GET /api/adapters.
5	 *
6	 * The server-side adapterRoutes() reads plugin manifests from disk and
7	 * maintains an in-process registry — neither is available in a CF Worker.
8	 * This handler reads the built-in adapter registry (always available) and
9	 * the disabled-adapter set from the DB-backed adapter-plugin-store shim.
10	 *
11	 * Auth: requires an authenticated actor (board or agent). Unauthenticated
12	 * requests receive 401.
13	 */
14	
15	import type { Hono } from "hono";
16	import { listServerAdapters, isOverridePaused } from "../../../../../server/src/adapters/registry.js";
17	import { BUILTIN_ADAPTER_TYPES } from "../../../../../server/src/adapters/builtin-adapter-types.js";
18	import { getDisabledAdapterTypes } from "../../../../../server/src/services/adapter-plugin-store.js";
19	import { createHyperdriveDb } from "../../db/hyperdrive.js";
20	import { resolveActorFromRequest } from "../../auth/resolve-actor.js";
21	import { resolveDeploymentMode } from "../env.js";
22	import type { Env } from "../env.js";
23	
24	export function registerAdapterRoutes(app: Hono<{ Bindings: Env }>): void {
25	  // -------------------------------------------------------------------------
26	  // GET /api/adapters — built-in adapters from registry (external adapters
27	  // require FS-backed plugin store not available in CF; built-ins always load)
28	  // -------------------------------------------------------------------------
29	  app.get("/api/adapters", async (c) => {
30	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
31	    const actor = await resolveActorFromRequest(c.req.raw, db, {
32	      deploymentMode: resolveDeploymentMode(c.env),
33	    });
34	    if (!actor) return c.json({ error: "Unauthorized" }, 401);
35	
36	    const adapters = listServerAdapters();
37	    const disabledSet = new Set(getDisabledAdapterTypes());
38	    const result = adapters
39	      .map((adapter) => ({
40	        type: adapter.type,
41	        label: adapter.type,
42	        source: "builtin" as const,
43	        modelsCount: (adapter.models ?? []).length,
44	        loaded: true,
45	        disabled: disabledSet.has(adapter.type),
46	        capabilities: {
47	          supportsInstructionsBundle: adapter.supportsInstructionsBundle ?? false,
48	          supportsSkills: Boolean(adapter.listSkills || adapter.syncSkills),
49	          supportsLocalAgentJwt: adapter.supportsLocalAgentJwt ?? false,
50	          requiresMaterializedRuntimeSkills: adapter.requiresMaterializedRuntimeSkills ?? false,
51	        },
52	        overridePaused: BUILTIN_ADAPTER_TYPES.has(adapter.type)
53	          ? isOverridePaused(adapter.type)
54	          : undefined,
55	      }))
56	      .sort((a, b) => a.type.localeCompare(b.type));
57	    return c.json(result);
58	  });
59	}
